const savings = $input.first().json.tokenSavings || {};
const baseline = String($('Resultado Baseline').first().json.baseline_output || '');
const optimized = String($('Resultado Otimizado').first().json.optimized_output || '');
const expected = ["LEAD-2048","Campinas/SP","R$ 850.000,00","05/08/2026 14:30","false"];
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const baselineNormalized = normalize(baseline);
const optimizedNormalized = normalize(optimized);
const factsPreserved = expected.every((fact) => {
  const normalized = normalize(fact);
  return baselineNormalized.includes(normalized) && optimizedNormalized.includes(normalized);
});
const format = (value) => Number.isFinite(Number(value)) ? Number(value).toLocaleString('pt-BR') : 'indisponível';
const percentage = Number.isFinite(Number(savings.percent)) ? Number(savings.percent).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%' : 'indisponível';
const output = [
  '## Baseline — sem otimização',
  baseline,
  '',
  '## Otimizado — Token Saver Balanced',
  optimized,
  '',
  '## Prova da primeira mensagem',
  '**Tokens de entrada reais:** ' + format(savings.before) + ' → ' + format(savings.after),
  '**Economia real:** ' + format(savings.saved) + ' tokens (' + percentage + ')',
  '**Medição:** ' + String(savings.measurement || 'indisponível'),
  '**5/5 fatos preservados:** ' + (factsPreserved ? 'sim' : 'não'),
  '**Mesma pergunta, tool, modelo e temperatura:** sim',
].join('\n');
return [{ json: {
  output,
  baseline_output: baseline,
  optimized_output: optimized,
  token_savings: savings,
  facts_preserved: factsPreserved,
  first_message_test: true,
  dataset_records: 240,
  model: 'models/gemini-2.5-flash'
} }];
